{"file_path":"src/errors.js","content":"/**
 * Error types used across the brace-expansion and glob-matching code. Each
 * carries the exact message the CLI must print to standard error.
 */

export class UsageError extends Error {
  constructor() {
    super('error: usage: cli.js expand|match')
  }
}

export class ExpandLineCountError extends Error {
  constructor() {
    super('error: expand needs exactly one pattern line')
  }
}

export class MatchNeedsPatternError extends Error {
  constructor() {
    super('error: match needs a pattern line')
  }
}

export class UnterminatedBracketError extends Error {
  constructor() {
    super('error: unterminated bracket in pattern')
  }
}

export class UnterminatedExtglobError extends Error {
  constructor() {
    super('error: unterminated extglob in pattern')
  }
}

export class TrailingBackslashError extends Error {
  constructor() {
    super('error: trailing backslash in pattern')
  }
}

export class RangeTooLongError extends Error {
  constructor() {
    super('error: range is too long')
  }
}
"}

