{"file_path":"src/brace.js","content":"/**
 * Brace expansion: `{a,b}`, `{1..4}`, `{a..d..2}` and nested combinations
 * thereof. Everything here operates on plain JS strings but is careful to
 * step by Unicode code points rather than UTF-16 code units.
 */

import { RangeTooLongError, TrailingBackslashError } from './errors.js'

const MAX_RANGE = 1000

function codePointAt(s, i) {
  const cp = s.codePointAt(i)
  return String.fromCodePoint(cp)
}

/** Throws TrailingBackslashError if `s` ends with an unescaped backslash. */
export function assertNoTrailingBackslash(s) {
  let i = 0
  while (i < s.length) {
    if (s[i] === '\\') {
      if (i + 1 >= s.length) throw new TrailingBackslashError()
      i += 2
    } else {
      i++
    }
  }
}

// Finds the index of the `}` matching the `{` at index `openIdx`, honouring
// nesting and backslash escapes. Returns -1 if there is none.
function findMatchingBrace(s, openIdx) {
  let depth = 1
  let i = openIdx + 1
  while (i < s.length) {
    const c = s[i]
    if (c === '\\') {
      if (i + 1 >= s.length) throw new TrailingBackslashError()
      i += 2
      continue
    }
    if (c === '{') {
      depth++
      i++
      continue
    }
    if (c === '}') {
      depth--
      if (depth === 0) return i
      i++
      continue
    }
    i++
  }
  return -1
}

// Splits `body` on `sep` characters that sit at nesting depth 0 relative to
// this body (braces inside the body add/remove depth), skipping escapes.
function splitTopLevel(body, sep) {
  const parts = []
  let depth = 0
  let cur = ''
  let i = 0
  while (i < body.length) {
    const c = body[i]
    if (c === '\\') {
      if (i + 1 >= body.length) throw new TrailingBackslashError()
      cur += c + body[i + 1]
      i += 2
      continue
    }
    if (c === '{') {
      depth++
      cur += c
      i++
      continue
    }
    if (c === '}') {
      depth--
      cur += c
      i++
      continue
    }
    if (c === sep && depth === 0) {
      parts.push(cur)
      cur = ''
      i++
      continue
    }
    cur += c
    i++
  }
  parts.push(cur)
  return parts
}

const INT_RE = /^[+-]?\d+$/

function digitsOf(s) {
  const sign = s[0] === '-' ? '-' : ''
  const rest = s[0] === '+' || s[0] === '-' ? s.slice(1) : s
  return { sign, digits: rest }
}

function hasLeadingZero(s) {
  const { digits } = digitsOf(s)
  return digits.length > 1 && digits[0] === '0'
}

// Attempts to interpret `body` as a range. Returns an array of alternative
// strings, or null when the body is not a valid range.
function tryRange(body) {
  const parts = body.split('..')
  if (parts.length !== 2 && parts.length !== 3) return null
  const [a, b, sRaw] = parts

  let step = 1
  if (parts.length === 3) {
    if (!INT_RE.test(sRaw)) return null
    step = Math.abs(parseInt(sRaw, 10))
    if (step === 0) return null
  }

  if (INT_RE.test(a) && INT_RE.test(b)) {
    const ai = parseInt(a, 10)
    const bi = parseInt(b, 10)
    const count = Math.floor(Math.abs(bi - ai) / step) + 1
    if (count > MAX_RANGE) throw new RangeTooLongError()
    const pad = hasLeadingZero(a) || hasLeadingZero(b)
    const width = pad ? Math.max(digitsOf(a).digits.length, digitsOf(b).digits.length) : 0
    const dir = bi >= ai ? 1 : -1
    const out = []
    for (let k = 0; k < count; k++) {
      const v = ai + dir * step * k
      const sign = v < 0 ? '-' : ''
      let digits = Math.abs(v).toString()
      if (pad) digits = digits.padStart(width, '0')
      out.push(sign + digits)
    }
    return out
  }

  const aChars = Array.from(a)
  const bChars = Array.from(b)
  if (aChars.length === 1 && bChars.length === 1 && /[A-Za-z]/.test(a) && /[A-Za-z]/.test(b)) {
    const ai = a.codePointAt(0)
    const bi = b.codePointAt(0)
    const count = Math.floor(Math.abs(bi - ai) / step) + 1
    if (count > MAX_RANGE) throw new RangeTooLongError()
    const dir = bi >= ai ? 1 : -1
    const out = []
    for (let k = 0; k < count; k++) {
      out.push(String.fromCodePoint(ai + dir * step * k))
    }
    return out
  }

  return null
}

// Finds the leftmost expandable group (a list or a valid range). Returns
// {start, end, alternatives} or null if there is none.
function findExpandableGroup(pattern) {
  let searchFrom = 0
  while (searchFrom < pattern.length) {
    // find next unescaped '{' at or after searchFrom
    let i = searchFrom
    let openIdx = -1
    while (i < pattern.length) {
      const c = pattern[i]
      if (c === '\\') {
        if (i + 1 >= pattern.length) throw new TrailingBackslashError()
        i += 2
        continue
      }
      if (c === '{') {
        openIdx = i
        break
      }
      i++
    }
    if (openIdx === -1) return null

    const closeIdx = findMatchingBrace(pattern, openIdx)
    if (closeIdx === -1) {
      // literal '{', resume search just after it
      searchFrom = openIdx + 1
      continue
    }

    const body = pattern.slice(openIdx + 1, closeIdx)
    const parts = splitTopLevel(body, ',')
    if (parts.length >= 2) {
      return { start: openIdx, end: closeIdx, alternatives: parts }
    }

    const rangeAlts = tryRange(body)
    if (rangeAlts !== null) {
      return { start: openIdx, end: closeIdx, alternatives: rangeAlts }
    }

    // neither a list nor a range: literal, resume just after the '{'
    searchFrom = openIdx + 1
  }
  return null
}

export function expandBrace(pattern) {
  const group = findExpandableGroup(pattern)
  if (!group) return [pattern]
  const { start, end, alternatives } = group
  const results = []
  for (const alt of alternatives) {
    const next = pattern.slice(0, start) + alt + pattern.slice(end + 1)
    for (const r of expandBrace(next)) results.push(r)
  }
  return results
}
"}

