 * Glob-style path matching: segment splitting on `/`, `**`, `*`, `?`,
 * bracket classes and `?()/*()/+()/@()/!()` extended groups.
 */

import { TrailingBackslashError, UnterminatedBracketError, UnterminatedExtglobError } from './errors.js'

function codePointAt(s, i) {
  const cp = s.codePointAt(i)
  return String.fromCodePoint(cp)
