// Splits `s` on `/`, skipping an escaped `/`. When `strict` is true, an
// unescaped trailing backslash is an error (used for the pattern); when
// false it is kept as a literal character (used for candidate paths).
export function splitSegments(s, strict) {
  const parts = []
  let cur = ''
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === '\\') {
      if (i + 1 >= s.length) {
        if (strict) throw new TrailingBackslashError()
        cur += c
        i++
        continue
      }
      cur += c + s[i + 1]
      i += 2
      continue
    }
    if (c === '/') {
      parts.push(cur)
      cur = ''
      i++
      continue
    }
    cur += c
    i++
  }
  parts.push(cur)
  return parts
