  // this level. Does not consume the stop character.
  parseTokens(stop) {
    const tokens = []
    while (!this.atEnd()) {
      const c = this.s[this.pos]
      if (stop && stop.includes(c)) break

      if (c === '\\') {
        this.pos++
        if (this.atEnd()) throw new TrailingBackslashError()
        const ch = codePointAt(this.s, this.pos)
        this.pos += ch.length
        tokens.push({ type: 'lit', ch })
        continue
      }

      if ((c === '?' || c === '*' || c === '+' || c === '@' || c === '!') && this.s[this.pos + 1] === '(') {
        this.pos += 2
        tokens.push(this.parseGroup(c))
        continue
      }

      if (c === '?') {
        this.pos++
        tokens.push({ type: 'any' })
        continue
      }

      if (c === '*') {
        while (this.s[this.pos] === '*') this.pos++
        tokens.push({ type: 'star' })
        continue
      }

      if (c === '[') {
        tokens.push(this.parseClass())
        continue
      }

      const ch = codePointAt(this.s, this.pos)
      this.pos += ch.length
      tokens.push({ type: 'lit', ch })
    }
    return tokens
  }

  parseGroup(kind) {
    const alts = []
    alts.push(this.parseTokens(['|', ')']))
    while (this.peek() === '|') {
      this.pos++
      alts.push(this.parseTokens(['|', ')']))
    }
    if (this.peek() !== ')') throw new UnterminatedExtglobError()
    this.pos++
    return { type: 'group', kind, alts }
  }

  parseClass() {
    // s[pos] === '['
    this.pos++
    let negate = false
    if (this.s[this.pos] === '!' || this.s[this.pos] === '^') {
      negate = true
      this.pos++
