      if (matchAlt(alt, text, pos, after)) return true
    }
    return false
  }

  if (kind === '*') {
    return matchStar(alts, text, pos, after, new Set())
  }

  if (kind === '+') {
    for (const alt of alts) {
      if (matchAlt(alt, text, pos, (p2) => matchStar(alts, text, p2, after, new Set()))) return true
    }
    return false
  }

  if (kind === '!') {
    for (let e = text.length; e >= pos; e--) {
      let anyMatches = false
      for (const alt of alts) {
        if (matchAlt(alt, text, pos, (p2) => p2 === e)) {
          anyMatches = true
          break
        }
      }
      if (!anyMatches) {
        if (after(e)) return true
      }
    }
    return false
  }

  return false
}

function matchSeq(tokens, ti, text, pos, cont) {
  if (ti === tokens.length) return cont(pos)
  const tok = tokens[ti]

  if (tok.type === 'lit') {
    if (pos < text.length && text[pos] === tok.ch) return matchSeq(tokens, ti + 1, text, pos + 1, cont)
    return false
  }

  if (tok.type === 'any') {
    if (pos < text.length) return matchSeq(tokens, ti + 1, text, pos + 1, cont)
    return false
  }

  if (tok.type === 'star') {
    for (let end = text.length; end >= pos; end--) {
