 * pattern on standard input; `node src/cli.js match` reads a pattern and then
 * one candidate path per line, and verdicts each candidate.
 */

import fs from 'node:fs'
import { assertNoTrailingBackslash, expandBrace } from './brace.js'
import { compilePattern, matchCompiled } from './glob.js'
import { ExpandLineCountError, MatchNeedsPatternError, UsageError } from './errors.js'

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'expand' && args[0] !== 'match')) {
    throw new UsageError()
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')
  const lines = splitLines(input)

  if (mode === 'expand') {
    if (lines.length !== 1) throw new ExpandLineCountError()
    const pattern = lines[0]
    assertNoTrailingBackslash(pattern)
    const expansions = expandBrace(pattern)
    return expansions.map((e) => e + '\n').join('')
  }

  // match
  if (lines.length < 1) throw new MatchNeedsPatternError()
  const pattern = lines[0]
  const candidates = lines.slice(1)
  assertNoTrailingBackslash(pattern)
  const expansions = expandBrace(pattern)
  const compiled = expansions.map((e) => compilePattern(e))

  const out = []
  for (const candidate of candidates) {
    const matched = compiled.some((c) => matchCompiled(c, candidate))
    out.push((matched ? '+ ' : '- ') + candidate + '\n')
  }
  return out.join('')
